package run.ikaros.identity;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.SecureRandom; import java.util.Base64; import java.util.UUID; import javax.crypto.SecretKeyFactory; import javax.crypto.spec.PBEKeySpec; import java.time.Instant; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class AuthenticationService{private static final int ITERATIONS=120000; private static final int KEY_BITS=256; private final PlatformUserRepository users;private final PasswordCredentialRepository credentials;private final SecuritySessionService sessions;private final UserService userService;private final PlatformRoleRepository roles;private final UserRoleRepository userRoles;private final SecureRandom random=new SecureRandom();public AuthenticationService(PlatformUserRepository u,PasswordCredentialRepository c,SecuritySessionService s,UserService us,PlatformRoleRepository r,UserRoleRepository ur){users=u;credentials=c;sessions=s;userService=us;roles=r;userRoles=ur;}public Mono<AuthenticationView> register(RegisterRequest q){String username=q.username().trim();String email=q.email()==null||q.email().isBlank()?null:q.email().trim().toLowerCase();Instant now=Instant.now();return users.save(new PlatformUserEntity(null,username,q.displayName().trim(),email,UserStatus.ACTIVE,now,now,null,0L,null)).onErrorMap(DuplicateKeyException.class,e->new ConflictException("用户名或邮箱已存在")).flatMap(u->credentials.save(new PasswordCredentialEntity(null,u.id(),hash(q.password()),now,now,null)).then(assignAdminIfFirstUser(u)).thenReturn(u)).flatMap(this::open);}private Mono<Void> assignAdminIfFirstUser(PlatformUserEntity user){return users.count().flatMap(count->count==1?roles.findByCode("admin").switchIfEmpty(Mono.error(new IllegalStateException("内置 admin 角色未初始化"))).flatMap(role->userRoles.save(new UserRoleEntity(null,user.id(),role.id(),Instant.now(),null))).then():Mono.empty());}public Mono<AuthenticationView> login(LoginRequest q){return users.findByUsername(q.username().trim()).flatMap(u->credentials.findByUserId(u.id()).filter(c->matches(q.password(),c.passwordHash())).switchIfEmpty(Mono.error(new NotFoundException("用户名或密码错误"))).then(Mono.just(u))).filter(u->u.status()==UserStatus.ACTIVE).switchIfEmpty(Mono.error(new NotFoundException("用户名或密码错误"))).flatMap(this::open);}private Mono<AuthenticationView> open(PlatformUserEntity u){return sessions.open(u.id(),"PASSWORD",Instant.now().plusSeconds(86400)).flatMap(s->userService.get(u.id()).map(v->new AuthenticationView(u.id(),s.id(),s.id().toString(),s.expiresAt(),v)));}private String hash(String p){byte[] salt=new byte[16];random.nextBytes(salt);try{byte[] key=derive(p.toCharArray(),salt);return "pbkdf2-sha256$"+ITERATIONS+"$"+b64(salt)+"$"+b64(key);}catch(Exception e){throw new IllegalStateException(e);}}private boolean matches(String p,String stored){try{String[] x=stored.split("\\$",4);if(x.length!=4)return false;return MessageDigest.isEqual(derive(p.toCharArray(),Base64.getUrlDecoder().decode(x[2])),Base64.getUrlDecoder().decode(x[3]));}catch(Exception e){return false;}}private byte[] derive(char[] p,byte[] salt)throws Exception{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(p,salt,ITERATIONS,KEY_BITS)).getEncoded();}private String b64(byte[] x){return Base64.getUrlEncoder().withoutPadding().encodeToString(x);}}
